26:     window.addEventListener('keydown', (e) => {
27:       if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
28:       if (e.repeat) return;
29:       this.keys.add(e.code);
30:       if (e.code === 'KeyE') this.actionPressed = true;
31:       if (e.code === 'Space') this.jumpPressed = true;
32:       if (e.code === 'KeyF') this.firePressed = true;
33:     });
34:     window.addEventListener('keyup', (e) => this.keys.delete(e.code));
35:     window.addEventListener('blur', () => {
36:       this.keys.clear();
37:       this.fireHeld = false;
38:     });
39:   }
