41:   _bindJoystick() {
42:     const base = document.getElementById('joystick');
43:     const knob = document.getElementById('stickKnob');
44:     if (!base) return;
45:     const radius = 44;
46:     let pid = null;
47: 
48:     const update = (e) => {
49:       const r = base.getBoundingClientRect();
50:       const cx = r.left + r.width / 2;
51:       const cy = r.top + r.height / 2;
52:       let dx = e.clientX - cx;
53:       let dy = e.clientY - cy;
54:       const len = Math.hypot(dx, dy);
55:       if (len > radius) { dx = (dx / len) * radius; dy = (dy / len) * radius; }
56:       knob.style.transform = `translate(${dx}px, ${dy}px)`;
57:       this.stick.x = dx / radius;
58:       this.stick.y = -dy / radius;
59:       this.stick.active = true;
60:       base.classList.add('active');
61:     };
62: 
63:     base.addEventListener('pointerdown', (e) => {
64:       e.preventDefault();
65:       e.stopPropagation();
66:       pid = e.pointerId;
67:       base.setPointerCapture(pid);
68:       update(e);
69:     });
70:     base.addEventListener('pointermove', (e) => {
71:       if (pid !== e.pointerId) return;
72:       e.preventDefault();
73:       update(e);
74:     });
75:     const end = (e) => {
76:       if (pid !== e.pointerId) return;
77:       pid = null;
78:       this.stick.x = 0; this.stick.y = 0; this.stick.active = false;
79:       knob.style.transform = 'translate(0px, 0px)';
80:       base.classList.remove('active');
81:     };
82:     base.addEventListener('pointerup', end);
83:     base.addEventListener('pointercancel', end);
84:   }
