86:   _bindButtons() {
87:     const bindHold = (id, onDown, onUp) => {
88:       const el = document.getElementById(id);
89:       if (!el) return;
90:       el.addEventListener('pointerdown', (e) => {
91:         e.preventDefault(); e.stopPropagation();
92:         el.classList.add('down');
93:         el.setPointerCapture?.(e.pointerId);
94:         onDown?.();
95:       });
96:       const up = (e) => {
97:         e.preventDefault();
98:         el.classList.remove('down');
99:         onUp?.();
100:       };
101:       el.addEventListener('pointerup', up);
102:       el.addEventListener('pointercancel', up);
103:       el.addEventListener('pointerleave', (e) => { if (e.buttons) up(e); });
104:     };
