106:     bindHold('btnFire', () => { this.fireHeld = true; this.firePressed = true; }, () => { this.fireHeld = false; });
107:     bindHold('btnAction', () => { this.actionPressed = true; });
108:     bindHold('btnJump', () => { this.jumpPressed = true; });
109:     bindHold('btnRun', () => {
110:       this.runToggle = !this.runToggle;
111:       document.getElementById('btnRun')?.classList.toggle('on', this.runToggle);
112:     });
113:   }
