115:   _bindCamera() {
116:     const el = this.canvas;
117:     el.addEventListener('pointerdown', (e) => {
118:       if (this.camPointer !== null) return;
119:       if (e.pointerType === 'mouse' && e.button !== 0) return;
120:       if (e.pointerType !== 'mouse' && e.clientX < window.innerWidth * 0.34) return;
121:       this.camPointer = e.pointerId;
122:       this.camStart = { x: e.clientX, y: e.clientY, t: performance.now(), moved: 0 };
123:       el.setPointerCapture?.(e.pointerId);
124:     });
125:     el.addEventListener('pointermove', (e) => {
126:       if (this.camPointer !== e.pointerId) return;
127:       const dx = e.clientX - this.camStart.x;
128:       const dy = e.clientY - this.camStart.y;
129:       this.camStart.x = e.clientX;
130:       this.camStart.y = e.clientY;
131:       this.camStart.moved += Math.abs(dx) + Math.abs(dy);
132:       this.camDX += dx;
133:       this.camDY += dy;
134:     });
135:     const end = (e) => {
136:       if (this.camPointer !== e.pointerId) return;
137:       const quick = performance.now() - this.camStart.t < 260 && this.camStart.moved < 8;
138:       if (e.pointerType === 'mouse' && quick) this.firePressed = true;
139:       this.camPointer = null;
140:     };
141:     el.addEventListener('pointerup', end);
142:     el.addEventListener('pointercancel', (e) => { if (this.camPointer === e.pointerId) this.camPointer = null; });
143:     el.addEventListener('contextmenu', (e) => e.preventDefault());
144:   }
145: 
