147:     const dx = this.camDX; const dy = this.camDY;
148:     this.camDX = 0; this.camDY = 0;
149:     return { dx, dy };
150:   }
151: 
152:   consumeFire() { const v = this.firePressed; this.firePressed = false; return v; }
153:   consumeAction() { const v = this.actionPressed; this.actionPressed = false; return v; }
154:   consumeJump() { const v = this.jumpPressed; this.jumpPressed = false; return v; }
155: 
156:   // Combined keyboard + touch movement, in local screen space.
157:   moveVector() {
158:     let x = this.stick.x;
159:     let y = this.stick.y;
160:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y += 1;
161:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y -= 1;
162:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
163:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
164:     const len = Math.hypot(x, y);
165:     if (len > 1) { x /= len; y /= len; }
166:     return { x: clamp(x, -1, 1), y: clamp(y, -1, 1), len: Math.min(1, len) };
167:   }
168: 
169:   isSprinting() {
170:     return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.runToggle || this.stick.y > 0.92;
171:   }
