329:       const ch = createCharacter({ shirt: choice(SHIRTS), pants: choice(PANTS), skin: randInt(0, 3), hat: Math.random() < 0.2 });
330:       ch.position.set(x, 0, z);
331:       this.scene.add(ch);
332:       const ped = { mesh: ch, x, z, targetX: x, targetZ: z, speed: rand(1.1, 1.7), dir: rand(0, Math.PI * 2), panic: 0, idle: rand(0, 0.8) };
333:       this.peds.push(ped);
334:       this.pickPedTarget(ped);
335:     }
336:   }
337: 
338:   pickPedTarget(ped) {
339:     const roads = CITY.roads;
340:     const axis = Math.random() < 0.5;
341:     const road = choice(roads);
342:     for (let tries = 0; tries < 6; tries++) {
343:       const tx = axis ? road + choice([-1, 1]) * rand(8.8, 10.2) : clamp(ped.x + rand(-45, 45), -235, 235);
344:       const tz = axis ? clamp(ped.z + rand(-45, 45), -235, 235) : road + choice([-1, 1]) * rand(8.8, 10.2);
345:       if (dist(tx, tz, ped.x, ped.z) > 8) { ped.targetX = tx; ped.targetZ = tz; return; }
346:     }
347:     ped.targetX = clamp(ped.x + rand(-30, 30), -235, 235);
348:     ped.targetZ = clamp(ped.z + rand(-30, 30), -235, 235);
349:   }
350: 
351:   buildBarrels() {
352:     const places = [];
353:     const roads = CITY.roads;
354:     for (let i = 0; i < 20; i++) {
355:       const road = choice(roads);
356:       const along = rand(-200, 200);
357:       const axis = Math.random() < 0.5;
358:       const off = choice([-1, 1]) * rand(8.6, 10.1);
359:       places.push(axis ? { x: road + off, z: along } : { x: along, z: road + off });
360:     }
361:     places.push({ x: 22, z: 35 }, { x: 38, z: 24 });
362:     for (const p of places) {
363:       if (dist(p.x, p.z, this.player.pos.x, this.player.pos.z) < 9) continue;
364:       const g = createBarrel();
365:       g.position.set(p.x, 0, p.z);
366:       g.rotation.y = rand(0, Math.PI * 2);
367:       this.scene.add(g);
368:       this.barrels.push({ group: g, pos: new THREE.Vector3(p.x, 0, p.z), alive: true, respawn: 0 });
369:     }
370:   }
371: 
372:   buildHealthPacks() {
373:     const spots = [
374:       { x: 10.4, z: -8 }, { x: -9.4, z: -30 }, { x: 30, z: -9.4 },
375:       { x: -30, z: 9.4 }, { x: 129.4, z: 30 },
376:     ];
377:     for (const s of spots) {
378:       const group = new THREE.Group();
379:       const box = new THREE.Mesh(
380:         new THREE.BoxGeometry(0.9, 0.9, 0.9),
381:         new THREE.MeshStandardMaterial({ color: 0xe8eef0, roughness: 0.4, metalness: 0.2 }),
382:       );
383:       const crossMat = new THREE.MeshStandardMaterial({ color: 0x1d7f45, emissive: 0x35ff7a, emissiveIntensity: 1.1 });
384:       const c1 = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.16, 0.02), crossMat);
385:       const c2 = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.52, 0.02), crossMat);
386:       c1.position.z = c2.position.z = 0.46;
387:       const c3 = c1.clone(); c3.position.z = -0.46;
388:       const c4 = c2.clone(); c4.position.z = -0.46;
389:       group.add(box, c1, c2, c3, c4);
390:       group.position.set(s.x, 0.55, s.z);
391:       this.scene.add(group);
392:       this.healthPacks.push({ group, pos: new THREE.Vector3(s.x, 0, s.z), active: true, respawn: 0 });
393:     }
394:   }
395: 
396:   // ---------------------------------------------------------------- main loop
397:   frame(now) {
398:     requestAnimationFrame((t) => this.frame(t));
399:     const dt = Math.min(0.05, Math.max(0, (now - this.lastFrame) / 1000));
400:     this.lastFrame = now;
401:     this.clock += dt;
402:     this.update(dt);
403:     this.renderer.render(this.scene, this.camera);
404:   }
405: 
406:   update(dt) {
407:     const p = this.player;
408:     this.world.update(dt, this.clock, p.inCar ? p.inCar.pos : p.pos);
409:     this.effects.update(dt);
410:     this.updateTraffic(dt);
411:     this.updatePeds(dt);
412:     this.updateBarrels(dt);
413:     this.updateHealthPacks(dt);
414: 
415:     if (!this.started) {
416:       this.updateAttract(dt);
417:     } else if (this.wasted) {
418:       this.wasteTimer -= dt;
419:       this.updateCamera(dt);
420:       this.updateMissionVisuals(dt);
421:       if (this.wasteTimer <= 0) this.respawn();
422:     } else if (this.playing) {
423:       this.updatePlaying(dt);
424:     }
425: 
426:     this.fireCd = Math.max(0, this.fireCd - dt);
427:     this.collideCd = Math.max(0, this.collideCd - dt);
428:     this.cameraShake = Math.max(0, this.cameraShake - dt * 2.6);
429:     this.updateAudio(dt);
430:     if (this.started) this.updateHud(dt);
431:   }
432: 
433:   updateAttract(dt) {
434:     this.attractT += dt;
435:     const a = this.attractT * 0.055;
436:     const r = 188;
437:     this.camera.position.set(Math.cos(a) * r, 58 + Math.sin(a * 1.6) * 12, Math.sin(a) * r);
438:     this.camera.lookAt(0, 14 + Math.sin(a * 0.7) * 4, 0);
439:     this.updateMissionVisuals(dt);
440:   }
441: 
442:   updatePlaying(dt) {
443:     const p = this.player;
444:     const cam = this.input.consumeCamera();
445:     this.camYaw -= cam.dx * 0.0052;
446:     this.camPitch = clamp(this.camPitch - cam.dy * 0.0038, -0.06, 0.92);
447:     if (Math.abs(cam.dx) + Math.abs(cam.dy) > 0.5) this.camManual = 2.4;
448:     this.camManual = Math.max(0, this.camManual - dt);
449: 
450:     this.spawnCopTimer -= dt;
451:     if (this.wanted > 0) {
452:       this.updateWanted(dt);
453:       if (this.spawnCopTimer <= 0 && this.police.length < this.wanted) {
454:         this.spawnCop();
455:         this.spawnCopTimer = Math.max(1.6, 4.2 - this.wanted * 0.45);
456:       }
457:     }
458:     this.updatePolice(dt);
459: 
460:     const action = this.input.consumeAction() || this.interactPressed;
461:     this.interactPressed = false;
462:     if (action) this.toggleVehicle();
463: 
464:     if (p.inCar) {
465:       this.updateDriving(dt);
466:       if (this.input.consumeFire() || this.input.fireHeld) {
467:         if (this.fireCd <= 0) { this.fireCd = 0.5; this.audio.horn(); }
468:       }
469:       this.input.consumeJump();
470:     } else {
471:       this.updateOnFoot(dt);
472:       if (this.input.consumeJump()) {
473:         if (p.grounded) { p.vy = 7.7; p.grounded = false; this.audio.thud(); }
474:       }
475:       if (this.input.consumeFire() || this.input.fireHeld) this.tryFire();
476:     }
477: 
478:     this.updateMission(dt);
479:     this.updateCamera(dt);
480:     this.updateMissionVisuals(dt);
481: 
482:     p.sinceDamage += dt;
483:     if (p.sinceDamage > 8 && p.health < 100 && !p.inCar) {
484:       p.health = Math.min(100, p.health + 5.5 * dt);
485:     }
486:   }
487: 
488:   updateOnFoot(dt) {
489:     const p = this.player;
490:     const mv = this.input.moveVector();
491:     const fwdX = Math.sin(this.camYaw); const fwdZ = Math.cos(this.camYaw);
492:     const rightX = Math.cos(this.camYaw); const rightZ = -Math.sin(this.camYaw);
493:     let dx = fwdX * mv.y + rightX * mv.x;
494:     let dz = fwdZ * mv.y + rightZ * mv.x;
495:     const len = Math.hypot(dx, dz);
496:     const sprint = this.input.isSprinting();
497:     const maxSpeed = sprint ? 8.1 : 4.6;
498:     if (len > 0.02) {
499:       dx /= len; dz /= len;
500:       p.yaw = angleLerp(p.yaw, Math.atan2(dx, dz), 1 - Math.exp(-13 * dt));
501:     }
502:     const target = len > 0.02 ? maxSpeed * Math.min(1, len) : 0;
503:     p.speed = damp(p.speed, target, 10, dt);
504: 
505:     if (p.speed > 0.05) {
506:       p.pos.x += dx * p.speed * dt;
507:       p.pos.z += dz * p.speed * dt;
508:     }
509: 
510:     // gravity / jump
511:     if (!p.grounded) {
512:       p.y += p.vy * dt;
513:       p.vy -= 23 * dt;
514:       if (p.y <= 0) { p.y = 0; p.vy = 0; p.grounded = true; }
515:     }
516: 
517:     // building collisions
518:     const pos = this.temp;
519:     pos.x = p.pos.x; pos.z = p.pos.z;
520:     for (const c of this.world.colliders) {
521:       if (Math.abs(pos.x - (c.minX + c.maxX) / 2) > 20 || Math.abs(pos.z - (c.minZ + c.maxZ) / 2) > 20) continue;
522:       if (resolveCircleRect(pos, 0.5, c)) {
523:         p.pos.x = pos.x; p.pos.z = pos.z;
524:       }
525:     }
526: 
527:     // vehicle collisions
528:     const allCars = [...this.vehicles, ...this.traffic, ...this.police];
529:     for (const car of allCars) {
530:       const dx2 = p.pos.x - car.pos.x;
531:       const dz2 = p.pos.z - car.pos.z;
532:       const d = Math.hypot(dx2, dz2);
533:       const min = car.type === 'van' ? 2.1 : 1.85;
534:       if (d < min && d > 0.0001) {
535:         p.pos.x = car.pos.x + (dx2 / d) * min;
536:         p.pos.z = car.pos.z + (dz2 / d) * min;
537:         if (car.commute && car.speed > 3 && this.collideCd <= 0) {
538:           this.collideCd = 0.8;
539:           p.health -= 6;
540:           this.hurt(0.2);
541:           p.pos.x += (dx2 / d) * 0.4;
542:           p.pos.z += (dz2 / d) * 0.4;
543:         }
544:       }
545:     }
546: 
547:     // world bounds
548:     p.pos.x = clamp(p.pos.x, -332, 332);
549:     p.pos.z = clamp(p.pos.z, -332, 332);
550: 
551:     const bob = this.playerMesh.userData.bob || 0;
552:     this.playerMesh.visible = true;
553:     this.playerMesh.position.set(p.pos.x, p.y + bob, p.pos.z);
554:     this.playerMesh.rotation.y = p.yaw;
555:     this.playerMesh.userData.gun.visible = true;
556:     animateCharacter(this.playerMesh, dt, p.speed, p.grounded);
557: 
558:     // interact hint
559:     const near = this.nearestVehicle(5.2);
560:     this.hud.action.textContent = near ? 'ENTER' : 'ENTER';
561:     if (near) this.hud.action.classList.add('ready');
562:     else this.hud.action.classList.remove('ready');
563:   }
564: 
565:   nearestVehicle(maxDist) {
566:     let best = null; let bestD = maxDist;
567:     for (const car of [...this.vehicles, ...this.traffic]) {
568:       const d = dist(car.pos.x, car.pos.z, this.player.pos.x, this.player.pos.z);
569:       if (d < bestD) { bestD = d; best = car; }
570:     }
571:     return best;
572:   }
573: 
574:   toggleVehicle() {
575:     const p = this.player;
576:     if (p.inCar) {
577:       const car = p.inCar;
578:       car.isPlayer = false;
579:       car.speed = 0;
580:       const side = new THREE.Vector3(Math.cos(car.heading), 0, -Math.sin(car.heading)).multiplyScalar(2.4);
581:       p.pos.set(car.pos.x + side.x, 0, car.pos.z + side.z);
582:       p.y = 0; p.vy = 0; p.grounded = true;
583:       p.inCar = null;
584:       p.speed = 0;
585:       this.playerMesh.visible = true;
586:       this.playerMesh.userData.gun.visible = true;
587:       this.hud.speedo.classList.remove('show');
588:       this.toast('On foot');
589:       this.audio.horn();
590:       return;
591:     }
592:     const car = this.nearestVehicle(5.2);
593:     if (!car) { this.toast('No vehicle nearby', 'red'); return; }
594:     p.inCar = car;
595:     car.isPlayer = true;
596:     car.speed = 0;
597:     if (car.commute) {
598:       car.commute = false;
599:       const idx = this.traffic.indexOf(car);
600:       if (idx >= 0) this.traffic.splice(idx, 1);
601:       this.crime(1);
602:       this.toast('Carjacked — witnesses called the cops', 'red', 2600);
603:     } else {
604:       this.toast('Vehicle acquired');
605:     }
606:     p.pos.copy(car.pos);
607:     this.playerMesh.visible = false;
608:     this.playerMesh.userData.gun.visible = false;
609:     this.hud.speedo.classList.add('show');
610:     this.camYaw = car.heading;
611:     this.camPitch = 0.24;
612:     this.updateCamera(0.001);
613:     this.audio.horn();
614:   }
615: 
616:   updateDriving(dt) {
617:     const p = this.player;
618:     const car = p.inCar;
619:     const mv = this.input.moveVector();
620:     const throttle = mv.y;
621:     // The trailing camera faces +Z, so screen-right is world -X; invert horizontal input
622:     // to keep right/left steering aligned with what the player sees.
623:     const steer = -mv.x;
624:     const braking = throttle < -0.1 && car.speed > 1;
625: 
626:     if (throttle > 0.05) {
627:       car.speed += car.accel * throttle * dt;
628:     } else if (throttle < -0.05) {
629:       if (car.speed > 0.4) car.speed -= 30 * Math.abs(throttle) * dt;
630:       else car.speed -= car.accel * 0.5 * Math.abs(throttle) * dt;
631:     } else {
632:       car.speed -= Math.sign(car.speed) * Math.min(Math.abs(car.speed), (2.1 + Math.abs(car.speed) * 0.055) * dt);
633:     }
634:     car.speed = clamp(car.speed, -12, car.maxSpeed);
635: 
636:     const speedFactor = clamp(Math.abs(car.speed) / 14, 0, 1);
637:     car.heading += steer * 1.95 * speedFactor * Math.sign(car.speed || 1) * dt;
638:     const fx = Math.sin(car.heading);
639:     const fz = Math.cos(car.heading);
640:     const nx = car.pos.x + fx * car.speed * dt;
641:     const nz = car.pos.z + fz * car.speed * dt;
642: 
643:     // building collisions
644:     const pos = this.temp;
645:     pos.x = nx; pos.z = nz;
646:     let hit = false;
647:     for (const c of this.world.colliders) {
648:       if (Math.abs(pos.x - (c.minX + c.maxX) / 2) > 24 || Math.abs(pos.z - (c.minZ + c.maxZ) / 2) > 24) continue;
649:       if (resolveCircleRect(pos, 1.9, c)) hit = true;
650:     }
651:     if (hit) {
652:       car.speed *= -0.12;
653:       if (Math.abs(car.speed) > 2 && this.collideCd <= 0) {
654:         this.collideCd = 0.35;
655:         this.audio.thud();
656:         this.cameraShake = Math.min(1, this.cameraShake + 0.45);
657:         this.effects.impact(pos.x, 0.8, pos.z);
658:         this.hurt(0.4);
659:       }
660:     }
661:     car.pos.x = clamp(pos.x, -330, 330);
662:     car.pos.z = clamp(pos.z, -330, 330);
663: 
664:     // traffic / parked collisions
665:     for (const other of [...this.vehicles, ...this.traffic]) {
666:       if (other === car) continue;
667:       const dx = car.pos.x - other.pos.x;
668:       const dz = car.pos.z - other.pos.z;
669:       const d = Math.hypot(dx, dz);
670:       if (d < 2.9 && d > 0.001) {
671:         car.pos.x = other.pos.x + (dx / d) * 2.9;
672:         car.pos.z = other.pos.z + (dz / d) * 2.9;
673:         if (this.collideCd <= 0 && Math.abs(car.speed) > 3) {
674:           this.collideCd = 0.35;
675:           const impact = Math.abs(car.speed);
676:           car.speed *= -0.18;
677:           other.speed *= 0.4;
678:           this.cameraShake = Math.min(1, this.cameraShake + Math.min(0.8, impact / 45));
679:           this.effects.impact((car.pos.x + other.pos.x) / 2, 0.75, (car.pos.z + other.pos.z) / 2);
680:           this.audio.thud();
681:           this.hurt(Math.min(8, impact * 0.35));
682:         }
683:       }
684:     }
685: 
686:     // police rams
687:     for (const cop of this.police) {
688:       const d = dist(cop.pos.x, cop.pos.z, car.pos.x, car.pos.z);
689:       if (d < 3.1 && this.collideCd <= 0 && cop.speed > 3) {
690:         this.collideCd = 0.4;
691:         car.speed *= 0.45;
692:         cop.speed *= 0.4;
693:         this.cameraShake = Math.min(1, this.cameraShake + 0.6);
694:         this.effects.impact((car.pos.x + cop.pos.x) / 2, 0.8, (car.pos.z + cop.pos.z) / 2);
695:         this.audio.thud();
696:         this.hurt(7);
697:       }
698:     }
699: 
700:     p.pos.copy(car.pos);
701:     car.group.position.set(car.pos.x, 0, car.pos.z);
702:     car.group.rotation.set(
703:       -clamp(throttle, 0, 1) * 0.025 + (braking ? 0.035 : 0),
704:       car.heading,
705:       -steer * 0.05 * speedFactor,
706:     );
707: 
708:     if (this.camManual <= 0) this.camYaw = damp(this.camYaw, car.heading, 2.4, dt);
709: 
710:     // headlights
711:     const night = this.world.night || 0;
712:     this.playerCarLight.intensity = night * 26;
713:     this.playerCarLight.position.set(car.pos.x + fx * 2, 0.9, car.pos.z + fz * 2);
714:     this.playerCarLightTarget.position.set(car.pos.x + fx * 22, 0.2, car.pos.z + fz * 22);
715:   }
716: 
717:   hurt(amount) {
718:     const p = this.player;
719:     p.sinceDamage = 0;
720:     if (p.inCar) {
721:       p.inCar.health -= amount;
722:       this.flashDamage();
723:       if (p.inCar.health <= 0) this.destroyPlayerCar();
724:     } else {
725:       p.health -= amount;
726:       this.flashDamage();
727:       this.cameraShake = Math.min(1.2, this.cameraShake + 0.35);
728:       if (p.health <= 0) this.die();
729:     }
730:   }
731: 
732:   flashDamage() {
733:     const el = this.hud.damage;
734:     if (!el) return;
735:     el.classList.add('hit');
736:     clearTimeout(this.damageTimer);
737:     this.damageTimer = setTimeout(() => el.classList.remove('hit'), 110);
738:   }
739: 
740:   destroyPlayerCar() {
741:     const p = this.player;
742:     const car = p.inCar;
743:     if (!car) return;
744:     this.effects.explosion(car.pos.x, 1, car.pos.z, 1.25);
745:     this.audio.explosion();
746:     this.cameraShake = 1.4;
747:     car.group.visible = false;
748:     p.inCar = null;
749:     p.pos.set(car.pos.x + 2.5, 0, car.pos.z + 2.5);
750:     p.y = 0; p.vy = 1; p.grounded = false;
751:     this.playerMesh.visible = true;
752:     this.playerMesh.userData.gun.visible = true;
753:     this.hud.speedo.classList.remove('show');
754:     this.hurt(30);
755:     this.toast('Vehicle destroyed', 'red');
756:   }
757: 
758:   die() {
759:     if (this.wasted) return;
760:     this.wasted = true;
761:     this.playing = false;
762:     this.wasteTimer = 3.4;
763:     this.hud.wasted.classList.remove('hidden');
764:     this.player.inCar = null;
765:     this.playerMesh.visible = false;
766:     this.hud.speedo.classList.remove('show');
767:     this.wanted = 0;
768:     for (const cop of this.police) this.scene.remove(cop.group);
769:     this.police = [];
770:     this.audio.updateSiren(false, this.clock);
771:   }
772: 
773:   respawn() {
774:     const p = this.player;
775:     this.wasted = false;
776:     this.playing = true;
777:     this.hud.wasted.classList.add('hidden');
778:     p.health = 100;
779:     p.cash = Math.max(0, p.cash - 100);
780:     p.inCar = null;
781:     p.pos.set(9.5, 0, 24);
782:     p.y = 0; p.vy = 0; p.grounded = true; p.speed = 0;
783:     this.playerMesh.visible = true;
784:     this.playerMesh.userData.gun.visible = true;
785:     this.wanted = 0;
786:     this.evadeTimer = 0;
787:     this.camYaw = Math.PI + 0.1;
788:     this.camPitch = 0.22;
789:     this.camera.position.set(30, 10, 30);
790:     this.newMission(true);
791:     this.toast('Patched up. One hundred dollars lighter.', '', 2600);
792:   }
793: 
794:   // ---------------------------------------------------------------- shooting
795:   tryFire() {
796:     if (!this.playing || this.player.inCar || this.fireCd > 0) return;
797:     this.fireCd = 0.155;
798:     this.audio.gunshot();
799:     this.crime(1);
800:     this.playerMesh.userData.rightArm.rotation.x = -1.2;
801:     this.cameraShake = Math.min(1, this.cameraShake + 0.18);
802: 
803:     const dir = new THREE.Vector3();
804:     this.camera.getWorldDirection(dir);
805:     const origin = new THREE.Vector3();
806:     this.camera.getWorldPosition(origin);
807:     const playerFocus = this.currentPos().clone();
808:     playerFocus.y += 1.35;
809: 
810:     // Aim assist: snap toward the nearest target close to the crosshair ray.
811:     let best = null; let bestScore = Infinity;
812:     const candidates = [];
813:     for (const cop of this.police) candidates.push({ kind: 'cop', obj: cop, x: cop.pos.x, y: 1.05, z: cop.pos.z });
814:     for (const b of this.barrels) if (b.alive) candidates.push({ kind: 'barrel', obj: b, x: b.pos.x, y: 0.6, z: b.pos.z });
815:     const tmp = new THREE.Vector3();
816:     for (const c of candidates) {
817:       tmp.set(c.x, c.y, c.z);
818:       const to = tmp.clone().sub(origin);
819:       const t = to.dot(dir);
820:       if (t <= 0 || t > 70) continue;
821:       const closest = origin.clone().addScaledVector(dir, t);
822:       const miss = closest.distanceTo(tmp);
823:       const ang = Math.abs(Math.atan2(miss, t));
824:       if (ang < 0.26 && miss < 4.5) {
825:         const score = ang * 10 + t * 0.01;
826:         if (score < bestScore) { bestScore = score; best = c; }
827:       }
828:     }
829:     if (best) {
830:       const aim = new THREE.Vector3(best.x, best.y, best.z).sub(origin).normalize();
831:       dir.lerp(aim, this.mobile ? 0.92 : 0.62).normalize();
832:     }
833: 
834:     // nearest wall along the shot
835:     let wallT = 140;
836:     for (const c of this.world.colliders) {
837:       const t = rayAABB(origin, dir, c);
838:       if (t < wallT) wallT = t;
839:     }
840:     if (dir.y < -0.001) {
841:       const t = (0.03 - origin.y) / dir.y;
842:       if (t > 0 && t < wallT) wallT = t;
843:     }
844:     const end = origin.clone().addScaledVector(dir, Math.min(wallT, 120));
845: 
846:     let hitKind = null; let hitObj = null; let hitT = wallT;
847:     for (const c of candidates) {
848:       const t = raySphere(origin, dir, c.x, c.y, c.z, c.kind === 'cop' ? 2.1 : 1.15, Math.min(wallT, 120));
849:       if (t < hitT) { hitT = t; hitKind = c.kind; hitObj = c.obj; }
850:     }
851:     if (hitKind === 'cop') {
852:       hitObj.health -= 16;
853:       this.effects.impact(hitObj.pos.x, 1.1, hitObj.pos.z, 0xffc27a);
854:       this.audio.hit();
855:       this.crime(1);
856:       if (hitObj.health <= 0) this.destroyCop(hitObj);
857:       end.copy(origin).addScaledVector(dir, hitT);
858:     } else if (hitKind === 'barrel') {
859:       this.explodeBarrel(hitObj);
860:       end.copy(origin).addScaledVector(dir, hitT);
861:     } else {
862:       this.effects.impact(end.x, Math.max(0.3, end.y), end.z, 0xffd9a0);
863:     }
864: 
865:     const muzzle = new THREE.Vector3();
866:     this.playerMesh.userData.gun.getWorldPosition(muzzle);
867:     muzzle.y += 0.08;
868:     this.effects.muzzle(muzzle.x, muzzle.y, muzzle.z, dir.x, dir.y, dir.z);
869:     this.effects.tracer(muzzle.x, muzzle.y, muzzle.z, end.x, end.y, end.z);
870:     this.player.panic = 0;
871: 
872:     // nearby pedestrians panic
873:     for (const ped of this.peds) {
874:       if (dist(ped.x, ped.z, this.player.pos.x, this.player.pos.z) < 34) {
875:         ped.panic = 5;
876:         const a = Math.atan2(ped.x - this.player.pos.x, ped.z - this.player.pos.z);
877:         ped.targetX = clamp(ped.x + Math.sin(a) * 30, -235, 235);
878:         ped.targetZ = clamp(ped.z + Math.cos(a) * 30, -235, 235);
879:       }
880:     }
881:   }
