883:   // ---------------------------------------------------------------- traffic
884:   updateTraffic(dt) {
885:     const roads = CITY.roads;
886:     for (const car of this.traffic) {
887:       if (!car.commute) continue;
888:       const lane = this.lanePoint(car.a.i, car.a.j, car.b.i, car.b.j, car.t);
889:       car.len = lane.len;
890:       car.t += (car.speed * dt) / Math.max(2, lane.len);
891:       if (car.t >= 1) {
892:         const oldA = car.a;
893:         car.a = car.b;
894:         const options = [];
895:         const { i, j } = car.a;
896:         if (i + 1 <= 8) options.push({ i: i + 1, j });
897:         if (i - 1 >= 0) options.push({ i: i - 1, j });
898:         if (j + 1 <= 8) options.push({ i, j: j + 1 });
899:         if (j - 1 >= 0) options.push({ i, j: j - 1 });
900:         const filtered = options.filter((o) => !(o.i === oldA.i && o.j === oldA.j));
901:         const next = filtered.length ? choice(filtered) : options[0];
902:         car.a = car.b;
903:         car.b = { i: next.i, j: next.j };
904:         car.t = 0;
905:       }
906:       const p = this.lanePoint(car.a.i, car.a.j, car.b.i, car.b.j, car.t);
907:       car.pos.set(p.x, 0, p.z);
908:       car.heading = angleLerp(car.heading, p.heading, 1 - Math.exp(-6 * dt));
909: 
910:       // Slow for cars ahead and for the player.
911:       let targetSpeed = car.baseSpeed;
912:       for (const other of this.traffic) {
913:         if (other === car) continue;
914:         const dx = other.pos.x - car.pos.x;
915:         const dz = other.pos.z - car.pos.z;
916:         const d = Math.hypot(dx, dz);
917:         if (d < 10 && dx * Math.sin(car.heading) + dz * Math.cos(car.heading) > 0) {
918:           targetSpeed = Math.min(targetSpeed, d * 1.2);
919:         }
920:       }
921:       const targetPos = this.currentPos();
922:       const pd = dist(targetPos.x, targetPos.z, car.pos.x, car.pos.z);
923:       if (pd < 9) targetSpeed = Math.min(targetSpeed, pd * 1.1);
924:       car.speed = damp(car.speed, targetSpeed, 3, dt);
925: 
926:       car.group.position.set(car.pos.x, 0, car.pos.z);
927:       car.group.rotation.y = car.heading;
928:     }
929:   }
