1228:   updateCamera(dt) {
1229:     const p = this.player;
1230:     const car = p.inCar;
1231:     const focus = this._tmpV.set(
1232:       this.currentPos().x,
1233:       car ? 1.35 : p.y + 1.45,
1234:       this.currentPos().z,
1235:     );
1236:     const distCam = car ? 10.2 : TOTAL.onFoot;
1237:     const pitch = this.camPitch;
1238:     const horiz = Math.cos(pitch) * distCam;
1239:     const desired = this._tmpV2.set(
1240:       focus.x - Math.sin(this.camYaw) * horiz,
1241:       focus.y + 0.5 + Math.sin(pitch) * distCam,
1242:       focus.z - Math.cos(this.camYaw) * horiz,
1243:     );
1244: 
1245:     const target = this.resolveCamera(focus, desired);
1246:     if (this.cameraBlend > 0) {
1247:       this.cameraBlend = Math.max(0, this.cameraBlend - dt / 0.45);
1248:       const t = 1 - this.cameraBlend;
1249:       const e = smoothstep(0, 1, t);
1250:       this.camera.position.lerpVectors(this.cameraBlendFrom, target, e);
1251:       const look = new THREE.Vector3().lerpVectors(this.cameraBlendLook, focus, e);
1252:       this.camera.lookAt(look);
1253:     } else {
1254:       const k = 1 - Math.exp(-13 * dt);
1255:       this.camera.position.lerp(target, k);
1256:       this.camera.lookAt(focus);
1257:     }
1258: 
1259:     if (this.cameraShake > 0.01) {
1260:       const s = this.cameraShake;
1261:       this.camera.position.x += rand(-s, s) * 0.16;
1262:       this.camera.position.y += rand(-s, s) * 0.12;
1263:       this.camera.rotation.z += rand(-s, s) * 0.015;
1264:     }
1265:   }
