1267:   resolveCamera(focus, desired) {
1268:     const steps = 9;
1269:     let lastX = focus.x; let lastY = focus.y; let lastZ = focus.z;
1270:     for (let i = 1; i <= steps; i++) {
1271:       const t = i / steps;
1272:       const x = focus.x + (desired.x - focus.x) * t;
1273:       const y = focus.y + (desired.y - focus.y) * t;
1274:       const z = focus.z + (desired.z - focus.z) * t;
1275:       let blocked = false;
1276:       if (y < 130) {
1277:         for (const c of this.world.colliders) {
1278:           if (c.tall < y - 0.4) continue;
1279:           if (pointInRect(x, z, c, 0.45)) { blocked = true; break; }
